#include <cstddef>
#include <cstdint>

namespace vkernels::kernels {

// CPU reference (oracle). C = alpha * A @ B + beta * C with A in [M, K],
// B in [K, N], C in [M, N], all bf16 row-major; fp32 accumulation; a single
