  store_matrix_sync(&sc[(warp_row*16)*BN + warp_col*16], c_frag, BN, mem_row_major);
  __syncthreads();
  for (int idx = tid; idx < BM*BN; idx += kTh) {
    int r = idx / BN, c = idx % BN;
    int gr = m_tile*BM + r, gc = n_tile*BN + c;
    if (gr < M && gc < N) {
      float v = alpha * sc[r*BN + c];
      if (beta != 0.0f) v += beta * bf16_to_f32_d(C[(size_t)gr*N + gc]);
      C[(size_t)gr*N + gc] = f2bf_d(v);
    }
  }
}
```

