THE FIX: filter out 0 readings BEFORE computing median and variance. A 0 reading is ALWAYS spurious (the kernel takes >0). If I drop 0s and only compute stats over positive readings, the median is robust and the loop converges naturally. If ALL readings in a batch are 0 (catastrophic), THEN I have a real problem and should fall back to chrono.

Let me implement: in bench_us, after collecting the batch, partition out zeros. If >0 positive readings exist, use them for stats. If all zeros, clear error and redo the batch once; if still all zeros, fall back to a single chrono measurement.

```cpp
static BenchResult bench_us(const std::function<void()>& launch,
                            cudaEvent_t start, cudaEvent_t stop,
                            int warmup = 5, int max_iters = 500) {
  (void)cudaDeviceSynchronize();
  for (int i = 0; i < warmup; ++i) launch();
  (void)cudaDeviceSynchronize();
  int iters = 20;
  while (iters <= max_iters) {
    std::vector<float> times;
    for (int i = 0; i < iters; ++i) {
      cudaEventRecord(start);
      launch();
      cudaEventRecord(stop);
      cudaEventSynchronize(stop);
      float ms = 0; cudaEventElapsedTime(&ms, start, stop);
      if (ms > 0.0f) times.push_back(ms * 1000.0f);   // drop spurious zeros
    }
    // If the whole batch came back zero (persistent driver glitch),
    // clear the sticky error and retry once.
    if (times.empty()) {
      (void)cudaGetLastError();
      for (int i = 0; i < iters; ++i) {
        cudaEventRecord(start); launch();
        cudaEventRecord(stop); cudaEventSynchronize(stop);
        float ms = 0; cudaEventElapsedTime(&ms, start, stop);
        if (ms > 0.0f) times.push_back(ms * 1000.0f);
      }
    }
    if (times.empty()) break;                          // give up, fall back
    double sum = 0; for (double t : times) sum += t;
    double mean = sum / times.size();
    double sum2 = 0; for (double t : times) sum2 += t * t;
    double var = sum2 / times.size() - mean * mean;
    double stddev = std::sqrt(std::max(0.0, var));
    if (stddev / mean < 0.03 || iters >= max_iters) {
      std::sort(times.begin(), times.end());
      return {times[0], times[times.size() / 2], mean};
    }
    iters *= 2;
  }
  // Last-resort fallback (persistent event failure): one chrono-timed
  // single launch between syncs. For kernels >= ~10 us the host-side
  // overhead is small relative to the kernel, so this is still honest.
  (void)cudaDeviceSynchronize(); (void)cudaGetLastError();
  auto t0 = std::chrono::high_resolution_clock::now();
  launch();
  (void)cudaDeviceSynchronize();
  auto t1 = std::chrono::high_resolution_clock::now();
  double us = std::chrono::duration<double, std::micro>(t1 - t0).count();
  return {us, us, us};
}
```

This is robust:
- Drops spurious 0 readings (most common case) → median is clean, loop converges.
- If a whole batch is 0, clears error + retries.
- If still all 0, falls back to chrono (rare).

Note: I removed the per-iteration retry (cleaner — the batch-level filter handles it). And the variance check now uses `times.size()` (only positive readings).

