```cpp
// Windowed chrono measurement (K warm launches between two device syncs),
// immune to the GB10 cudaEventElapsedTime flakiness that affects single-
// launch event timing. Repeats `repeats` windows; reports the min and
// median per-launch latency. Host launch overhead cancels across the K
// launches in each window. For kernels >= ~10 us this is as honest as
// event timing and far more robust.
static BenchResult bench_window(const std::function<void()>& launch,
                                int k = 30, int repeats = 25) {
  (void)cudaDeviceSynchronize();
  for (int i = 0; i < 10; ++i) launch();        // warmup
  (void)cudaDeviceSynchronize();
  std::vector<double> per;                      // per-launch us, one per window
  for (int r = 0; r < repeats; ++r) {
    (void)cudaDeviceSynchronize();
    auto t0 = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < k; ++i) launch();
    (void)cudaDeviceSynchronize();
    auto t1 = std::chrono::high_resolution_clock::now();
    double us = std::chrono::duration<double, std::micro>(t1 - t0).count() / k;
    per.push_back(us);
  }
  std::sort(per.begin(), per.end());
  double sum = 0; for (double t : per) sum += t;
  return {per[0], per[per.size() / 2], sum / per.size()};
}
```

