// f32 -> bf16 RNE (VERBATIM moe_device.hip::f2bf / f32bits_to_bf16).
// fp8->bf16 is lossless; used to stage sQt[sK] in the wmma kernel.
static __device__ __forceinline__ uint16_t f2bf(float f) {
  union { float f; uint32_t u; } x;
  x.f = f;
  uint32_t b = x.u;
  uint32_t lsb = (b >> 16) & 1u;
  b += 0x7FFFu + lsb;
  return static_cast<uint16_t>(b >> 16);
