```cpp
namespace {

// Once-per-process opt-in: GB10's sharedMemPerBlockOptin (99 KB) is RAISED
// (unlike gfx942's, which silently fails past 64 KB -- see the KB note
// mi300a-dynamic-lds-no-optin), so all three kernels can launch up to the
// device cap. Needed at H=128 (wmma 74,496 B; fp32-Q 98,432 B; fp8-Q
// 49,920 B -- all > the 48 KB non-optin cap). Set ONCE per kernel
// instantiation (cudaFuncAttribute persists; setting it every launch, as
// in a timing loop, perturbs the event clock -- mirrors gemm_bf16.cu).
struct OptIn {
  int cap;
  OptIn() {
    cudaDeviceProp p;
    (void)cudaGetDeviceProperties(&p, 0);
    cap = (int)p.sharedMemPerBlockOptin;
    (void)cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel,
                               cudaFuncAttributeMaxDynamicSharedMemorySize, cap);
    (void)cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel_fp8q,
                               cudaFuncAttributeMaxDynamicSharedMemorySize, cap);
    (void)cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel_mfma,
                               cudaFuncAttributeMaxDynamicSharedMemorySize, cap);
  }
};
const OptIn& opt_in() {
  static const OptIn o;
  return o;
}

void dsa_topk_logits_dispatch(int batch_size, int num_heads, int head_dim,
                              int block, int max_table_len, int max_seq_len,
                              int split_kv, const void* q_fp8,
                              const void* kvcache_u8, const void* weight,
                              const void* seq_lens, const void* page_table,
                              void* out, int variant) {
  if (batch_size <= 0 || max_table_len <= 0) return;
  if (num_heads <= 0 || head_dim <= 0 || block <= 0) return;

  const OptIn& oi = opt_in();   // raises the dynamic-LDS cap once

  dim3 grid(batch_size, split_kv, 1);

  const bool want_mfma  = (variant == 3) || (variant == 0);
  const bool want_fp32q = (variant == 1) || (variant == 0);
  const bool want_fp8q  = (variant == 2) || (variant == 0);

  const int kBK = 64;
  // mfma (wmma) variant: H%16==0, D%64==0, B%16==0, H/16 <= 8 (the kMaxNF
  // register cap on GB10; gfx942 admits H up to 480 via its more abundant
  // VGPR file -- the GB10 wmma port is limited to the GLM-5.3 family
  // H in {32,64,128}). Footprint = (D*H + B*kBK)*2 + (H+B)*4 + B*H*4 (the
  // sAcc[B][H] reduction buffer the wmma port needs -- the AMD fragment-
  // layout warp-shuffle reduction cannot be replicated with wmma).
  const int mfma_footprint =
      (head_dim * num_heads + block * kBK) * 2 +
      (num_heads + block) * (int)sizeof(float) +
      block * num_heads * (int)sizeof(float);
  if (want_mfma && (num_heads % 16) == 0 && (head_dim % 64) == 0 &&
      (block % 16) == 0 && (num_heads / 16) <= 8 &&
      mfma_footprint <= oi.cap) {
    dim3 blockdim((block / 16) * 32);
    dsa_topk_logits_kernel_mfma<<<grid, blockdim, mfma_footprint, 0>>>(
        reinterpret_cast<const uint8_t*>(q_fp8),
        reinterpret_cast<const uint8_t*>(kvcache_u8),
        reinterpret_cast<const float*>(weight),
        reinterpret_cast<const int32_t*>(seq_lens),
        reinterpret_cast<const int32_t*>(page_table),
        reinterpret_cast<float*>(out),
        num_heads, head_dim, block, max_table_len, max_seq_len, split_kv);
    return;
  }

  // fp32-Q variant.
  const int fp32q_footprint = (num_heads * head_dim + num_heads +
                               block * head_dim + block) * (int)sizeof(float);
  if (want_fp32q && fp32q_footprint <= oi.cap) {
    dim3 blockdim(block);
    dsa_topk_logits_kernel<<<grid, blockdim, fp32q_footprint, 0>>>(
        reinterpret_cast<const uint8_t*>(q_fp8),
        ...);
    return;
  }

  // fp8-Q variant.
  const int fp8q_footprint = (num_heads + block * head_dim + block) *
                             (int)sizeof(float) + num_heads * head_dim;
  if (want_fp8q && fp8q_footprint <= oi.cap) {
    dim3 blockdim(block);
    dsa_topk_logits_kernel_fp8q<<<grid, blockdim, fp8q_footprint, 0>>>(
        ...);
    return;
  }

  // Refuse.
  std::fprintf(stderr,
      "vk_cuda_dsa_topk_logits: indexer (H=%d D=%d B=%d) exceeds GB10's %d B "
      "dynamic-LDS cap under ALL of mfma (%d B), fp32-Q (%d B) and fp8-Q (%d B). "
      "Refusing (output left as the caller provided).\n",
      num_heads, head_dim, block, oi.cap,
      mfma_footprint, fp32q_footprint, fp8q_footprint);
}
}  // namespace

void dsa_topk_logits(...) { dsa_topk_logits_dispatch(..., 0); }
void dsa_topk_logits_with_variant(..., int variant) {
