### dsa_topk_logits_kernel_mfma (wmma) — the port
This is the new design. Let me write it carefully.

```cpp
// bf16 wmma variant of dsa_topk_logits_kernel -- the launcher's FAST path
// for the GLM-5.3 indexer family (H a multiple of 16, D a multiple of 64,
// B a multiple of 16, H/16 <= kMaxNF=8; see the dispatcher's fit check
// below). Mirrors dsa.hip's dsa_topk_logits_kernel_mfma: the per-page
// [B, H] = Q[H,D] @ K[B,D]^T dot matrix is factored through bf16 tensor
// cores (nvcuda::wmma 16x16x16, the verified counterpart to gfx942's
// __builtin_amdgcn_mfma_f32_16x16x16bf16_1k), then the ReLU + gated H-sum
// + per-token k_scale run in fp32.
//
// The AMD kernel reduced the 16x16 C fragment in-registers via a 4-step
// __shfl_xor (the verified 16x16 fragment lays each head on a fixed lane).
// That reduction is fragment-layout-specific and does NOT port to wmma
// (wmma's per-lane .x[] mapping is implementation-defined), so this kernel
// store_matrix_sync's each 16x16 fragment to a shared sAcc[B][H] buffer
// and does a plain gated H-sum per row (the gemm_bf16.cu epilogue pattern).
// sAcc adds B*H*4 bytes vs the gfx942 footprint; at H=128 that is 74,496 B,
// under GB10's 101,376 B opt-in cap (cudaFuncSetAttribute works on GB10,
// unlike gfx942 -- see the launcher's opt-in below).
//
// kMaxNF caps the held accumulator fragments at 8 (H <= 128) to stay within
// GB10's 255-register/thread limit (8 fragments * 8 floats/lane + a/b = 80
// regs). The GLM-5.3 family is H in {32, 64, 128} (kNF in {2, 4, 8}); larger
// H admitted by the shared gfx942 fits function (up to 480) falls back to
// the scalar variants on GB10. ...
static constexpr int kMmaK = 16;   // one bf16 wmma reduces K = 16
static constexpr int kBK    = 64;  // K-tile (fixed); D is a multiple of 64
static constexpr int kMaxNF = 8;   // column / head fragments (H <= 128)

__global__ void dsa_topk_logits_kernel_mfma(
    const uint8_t* __restrict__ q_fp8,
    const uint8_t* __restrict__ kvcache_u8,
    const float* __restrict__ weight,
    const int32_t* __restrict__ seq_lens,
    const int32_t* __restrict__ page_table,
    float* __restrict__ out,
    int H, int D, int B, int max_table_len, int max_seq_len, int split_kv) {
  const int kNF    = H / 16;           // column / head fragments
  const int kWarps = B / 16;           // one warp per 16-row fragment
  const int kTh    = kWarps * 32;      // threads per block (= B*2)

  const int b = blockIdx.x;
  const int pid_split = blockIdx.y;
  const int tid  = threadIdx.x;        // 0..kTh-1
  const int warp = tid >> 5;           // 0..kWarps-1
  const int row_base = warp * 16;      // this warp's 16 rows (j)

  const int seq_len = seq_lens[b];
  const int np_total = (seq_len + B - 1) / B;
  const int stride = (np_total + split_kv - 1) / split_kv;
  const int i_start = pid_split * stride;
  const int rem = np_total - i_start;
  const int n_iters = (rem <= 0) ? 0 : (stride < rem ? stride : rem);
  if (n_iters <= 0) return;

  extern __shared__ float smem[];
  uint16_t* sQt = reinterpret_cast<uint16_t*>(smem);              // D * H
  float*    sGate = reinterpret_cast<float*>(sQt + (size_t)D * H);     // H
  uint16_t* sK = reinterpret_cast<uint16_t*>(sGate + H);          // B * kBK
  float*    sKscale = reinterpret_cast<float*>(sK + (size_t)B * kBK);  // B
  float*    sAcc = sKscale + B;                                   // B * H

  // --- cooperative load Q transposed as bf16 sQt[D][H] once per block ---
  // Q is laid out [H][D] (q[h*D + d] = Q[h,d]); sQt is the TRANSPOSE
  // [D][H] so the wmma B fragment (sQt[K-row=d][N-col=h]) reads Q[h,d]
  // in one bf16 load. fp8 -> fp32 -> bf16 is lossless (every fp8 e4m3fnuz
  // finite value is exactly representable in bf16).
  const uint8_t* qp = q_fp8 + (size_t)b * H * D;
  for (int idx = tid; idx < H * D; idx += kTh) {
    const int h = idx / D;
    const int d = idx % D;
    sQt[(size_t)d * H + h] = f2bf(fp8e4m3fnuz_to_f32(qp[(size_t)h * D + d]));
  }
  const float* gp = weight + (size_t)b * H;
  for (int h = tid; h < H; h += kTh) sGate[h] = gp[h];
  __syncthreads();

  fragment<matrix_a, 16, 16, 16, __nv_bfloat16, row_major> a_frag;
  fragment<matrix_b, 16, 16, 16, __nv_bfloat16, row_major> b_frag;
  fragment<accumulator, 16, 16, 16, float> c_frag[kMaxNF];

  for (int it = 0; it < n_iters; ++it) {
    const int pg = i_start + it;
    const int32_t page = page_table[(size_t)b * max_table_len + pg];
    const uint8_t* kbase = kvcache_u8 + (size_t)page * (B * (D + 4));

    // Per-token scales: load ONCE per page (the trailing B*4 bytes).
    for (int j = tid; j < B; j += kTh)
      sKscale[j] = reinterpret_cast<const float*>(kbase + B * D)[j];

    for (int nf = 0; nf < kNF; ++nf)
      fill_fragment(c_frag[nf], 0.0f);

    // K-tiles: D/kBK of them, each kBK wide. A K-tile is consumed by
    // kBK/kMmaK = 4 wmma mma_syncs; a_frag is loaded once per k0 and
    // reused across all kNF column fragments.
    for (int kt = 0; kt < D / kBK; ++kt) {
      for (int idx = tid; idx < B * kBK; idx += kTh) {
        const int row = idx / kBK;          // 0..B-1 (KV token j)
        const int col = idx % kBK;          // 0..kBK-1 (local K-col)
        const int gcol = kt * kBK + col;
        sK[(size_t)row * kBK + col] =
            f2bf(fp8e4m3fnuz_to_f32(kbase[(size_t)row * D + gcol]));
      }
      __syncthreads();

      #pragma unroll
      for (int kk = 0; kk < kBK; kk += kMmaK) {
        load_matrix_sync(a_frag, (const __nv_bfloat16*)&sK[row_base * kBK + kk], kBK);
        #pragma unroll
        for (int nf = 0; nf < kNF; ++nf) {
          const int gd0 = kt * kBK + kk;
          load_matrix_sync(b_frag, (const __nv_bfloat16*)&sQt[(size_t)gd0 * H + nf * 16], H);
          mma_sync(c_frag[nf], a_frag, b_frag, c_frag[nf]);
        }
      }
      __syncthreads();                       // before reloading sK next tile
    }

    // --- store the per-page [B, H] dot matrix to shared, then gated reduce ---
    for (int nf = 0; nf < kNF; ++nf)
      store_matrix_sync(&sAcc[(size_t)row_base * H + nf * 16], c_frag[nf], H, mem_row_major);
    __syncthreads();

    // Epilogue: each thread handles some j (distributed across kTh), does the
    // full gated H-sum, and writes out if t < seq_len (caller zeroed `out`).
    for (int j = tid; j < B; j += kTh) {
      float partial = 0.0f;
      const float* arow = sAcc + (size_t)j * H;
      for (int h = 0; h < H; ++h) {
        float d = arow[h];
        if (d < 0.0f) d = 0.0f;            // ReLU (max(0, raw))
        partial += sGate[h] * d;
      }
      const int t = pg * B + j;
      if (t < seq_len)
        out[(size_t)b * max_seq_len + t] = sKscale[j] * partial;
    }
    __syncthreads();                       // before next page's sKscale + sK
  }
}
```

