namespace {
// Opt in to the larger-than-default (48 KB) dynamic shared region ONCE per
// kernel. GB10's sharedMemPerBlockOptin is 101,376 B (vs gfx942's 64 KB
// NON-OPTIN cap -- cudaFuncSetAttribute WORKS on GB10, verified), so the
// largest admitted footprint (fp32-Q at H=128: (128*128+128+64*128+64)*4 =
// 98,432 B) fits. Like the gemm_bf16 launcher, the opt-in is set in a
// static initializer so a tight timing loop does not perturb the event
// clock.
struct dyn_shmem_optin {
  dyn_shmem_optin() {
    cudaDeviceProp p;
    (void)cudaGetDeviceProperties(&p, 0);
    int cap = (int)p.sharedMemPerBlockOptin;
    (void)cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel,
                               cudaFuncAttributeMaxDynamicSharedMemorySize, cap);
    (void)cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel_fp8q,
                               cudaFuncAttributeMaxDynamicSharedMemorySize, cap);
    (void)cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel_mfma,
                               cudaFuncAttributeMaxDynamicSharedMemorySize, cap);
  }
};
}  // namespace
```
