Let me write the dispatcher:
```cpp
namespace {
void dsa_topk_logits_dispatch(int batch_size, int num_heads, int head_dim,
                              int block, int max_table_len, int max_seq_len,
                              int split_kv, const void* q_fp8,
                              const void* kvcache_u8, const void* weight,
                              const void* seq_lens, const void* page_table,
                              void* out, int variant) {
  if (batch_size <= 0 || max_table_len <= 0) return;
  if (num_heads <= 0 || head_dim <= 0 || block <= 0) return;

  // Opt in to the larger-than-default dynamic shared region ONCE (see
  // dyn_shmem_optin above). The static guard also queries the cap.
  static const dyn_shmem_optin optin;
  (void)optin;
  static int cap = [] {
    cudaDeviceProp p; (void)cudaGetDeviceProperties(&p, 0);
    return (int)p.sharedMemPerBlockOptin;
  }();

  const int H = num_heads, D = head_dim, B = block;
  dim3 grid(batch_size, split_kv, 1);

  const bool want_mfma  = (variant == 3) || (variant == 0);
  const bool want_fp32q = (variant == 1) || (variant == 0);
  const bool want_fp8q  = (variant == 2) || (variant == 0);

  // Fast path: the bf16 wmma kernel (Matrix-Core). Needs H%16==0,
  // D%64==0, B%16==0, H/16 <= kMaxNF=8 (register cap; the GLM-5.3
  // family is H in {32,64,128}). GB10's opt-in cap (101,376 B) admits
  // the sAcc-inclusive footprint at H=128 (74,496 B).
  const int shmem_mfma = (D * H + B * kBK) * 2 + (H + B) * (int)sizeof(float)
                         + B * H * (int)sizeof(float);
  if (want_mfma && H % 16 == 0 && D % 64 == 0 && B % 16 == 0 &&
      H / 16 <= kMaxNF && shmem_mfma <= cap) {
    dim3 blockdim((B / 16) * 32);
    dsa_topk_logits_kernel_mfma<<<grid, blockdim, shmem_mfma, 0>>>(
        reinterpret_cast<const uint8_t*>(q_fp8),
        reinterpret_cast<const uint8_t*>(kvcache_u8),
        reinterpret_cast<const float*>(weight),
        reinterpret_cast<const int32_t*>(seq_lens),
        reinterpret_cast<const int32_t*>(page_table),
        reinterpret_cast<float*>(out),
        H, D, B, max_table_len, max_seq_len, split_kv);
    return;
  }

  // fp32-Q kernel (Q dequanted once into shared) for shapes that fit the
  // larger fp32-Q footprint. GB10's opt-in cap admits H=128 (98,432 B).
  const int shmem_fp32q = (H * D + H + B * D + B) * (int)sizeof(float);
  if (want_fp32q && shmem_fp32q <= cap) {
    dim3 blockdim(B);
    dsa_topk_logits_kernel<<<grid, blockdim, shmem_fp32q, 0>>>(
        reinterpret_cast<const uint8_t*>(q_fp8),
        reinterpret_cast<const uint8_t*>(kvcache_u8),
        reinterpret_cast<const float*>(weight),
        reinterpret_cast<const int32_t*>(seq_lens),
        reinterpret_cast<const int32_t*>(page_table),
        reinterpret_cast<float*>(out),
        H, D, B, max_table_len, max_seq_len, split_kv);
    return;
  }

  // fp8-Q kernel (Q staged raw, dequantised on the fly in the dot loop with
  // the SAME helper -- bit-identical output to the fp32-Q kernel) for shapes
  // that fit the smaller fp8-Q footprint.
  const int shmem_fp8q = (H + B * D + B) * (int)sizeof(float) + H * D;
  if (want_fp8q && shmem_fp8q <= cap) {
    dim3 blockdim(B);
    dsa_topk_logits_kernel_fp8q<<<grid, blockdim, shmem_fp8q, 0>>>(
        reinterpret_cast<const uint8_t*>(q_fp8),
        reinterpret_cast<const uint8_t*>(kvcache_u8),
        reinterpret_cast<const float*>(weight),
        reinterpret_cast<const int32_t*>(seq_lens),
        reinterpret_cast<const int32_t*>(page_table),
        reinterpret_cast<float*>(out),
        H, D, B, max_table_len, max_seq_len, split_kv);
    return;
  }

  // No admitted variant. REFUSE the shape (mirrors the HIP dispatcher);
  // the caller zeroed `out`, which is what stays.
  std::fprintf(stderr,
      "vk_cuda_dsa_topk_logits: indexer (H=%d D=%d B=%d) exceeds the "
      "device's %d B opt-in dynamic-shared cap under ALL of wmma (%d B), "
      "fp32-Q (%d B) and fp8-Q (%d B). Refusing (output left as the "
      "caller provided).\n",
      H, D, B, cap, shmem_mfma, shmem_fp32q, shmem_fp8q);
}
}  // namespace
```

Hmm wait — the order. On GB10, at H=128: wmma (74,496) fits, fp32-Q (98,432) fits, fp8-Q (49,920) fits. The dispatcher picks wmma FIRST (Matrix-Core, what we want to bench). At H=32: wmma (24,960) fits → wmma. At H=64: wmma (41,472) fits → wmma. So for ALL GLM-5.3 family shapes (H ∈ {32,64,128}), the AUTO dispatcher picks wmma. The fp32-Q and fp8-Q are only hit via explicit variant=1/2 (the test forces them at H=32). ✓.

But wait — the test also has small shapes (H ∈ {1,2,4}, not multiples of 16). Those REFUSE wmma (H%16≠0), fall to fp32-Q (tiny footprint). ✓.

And `{1, 4, 16, 8, ...}`: H=4, D=16, B=8. wmma: H%16=4≠0 → refuse. fp32-Q: (4*16+4+8*16+8)*4 = 816 B ≤ cap → fp32-Q. ✓. (B=8 is not a multiple of 16, but fp32-Q doesn't require B%16==0 — it's scalar, launches blockDim=B=8.) ✓.

