void dsa_topk_logits_dispatch_cuda(int batch_size, int num_heads, int head_dim,
                                   int block, int max_table_len, int max_seq_len,
                                   int split_kv, const void* q_fp8,
                                   const void* kvcache_u8, const void* weight,
                                   const void* seq_lens, const void* page_table,
                                   void* out, int variant) {
  if (batch_size <= 0 || max_table_len <= 0) return;
  if (num_heads <= 0 || head_dim <= 0 || block <= 0) return;
  dim3 grid(batch_size, split_kv, 1);

  const bool want_mfma  = (variant == 3) || (variant == 0);
  const bool want_fp32q = (variant == 1) || (variant == 0);
  const bool want_fp8q  = (variant == 2) || (variant == 0);

  // --- MFMA fast path (wmma 16x16x16 bf16) ---
  if (want_mfma && ::vkernels::kernels::dsa_topk_logits_fits_lds_mfma(num_heads, head_dim, block)) {
    // GB10-specific: the wmma kernel stages the [B,H] accumulator in DYNAMIC
    // shared (store_matrix_sync -> sAcc[B][H]), so the total request is
    // static + B*H*4. gfx942's host cap (dsa_topk_logits_fits_lds_mfma,
    // static-only, 64 KB non-optin) admits this shape, but GB10's wmma
    // kernel additionally needs (a) the dynamic region to fit the opt-in
    // cap (101,376 B on GB10, opt-in WORKS unlike gfx942) and (b) the
    // block thread count (B/16)*(H/16)*32 <= maxThreadsPerBlock (1024).
    constexpr int kBK = 64;
    const int static_bytes = (head_dim * num_heads + block * kBK) * 2 +
                             (num_heads + block) * 4;
    const int dyn_bytes = block * num_heads * (int)sizeof(float);
    int optin = 0, max_th = 0;
    (void)cudaDeviceGetAttribute(&optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, 0);
    (void)cudaDeviceGetAttribute(&max_th, cudaDevAttrMaxThreadsPerBlock, 0);
    const int kTh = (block / 16) * (num_heads / 16) * 32;
    if (optin > 0 && static_bytes + dyn_bytes <= optin && kTh <= max_th) {
      static const bool inited = [] {
        cudaFuncSetAttribute((const void*)dsa_topk_logits_kernel_mfma,
            cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_bytes);
        return true;
      }();
      (void)inited;
      dim3 blockdim(kTh);
      dsa_topk_logits_kernel_mfma<<<grid, blockdim, dyn_bytes, 0>>>(
          ..., num_heads, head_dim, block, max_table_len, max_seq_len, split_kv);
      return;
    }
    // else fall through to fp32-Q / fp8-Q (the scalar variants don't need
    // the dynamic accumulator staging, so they may fit when the wmma
    // variant's [B,H] staging busts the opt-in cap or the thread limit).
  }

  // --- fp32-Q path ---
  if (want_fp32q && ::vkernels::kernels::dsa_topk_logits_fits_lds(num_heads, head_dim, block)) {
    const int shmem = (num_heads * head_dim + num_heads + block * head_dim + block) * sizeof(float);
    dim3 blockdim(block);
    dsa_topk_logits_kernel<<<grid, blockdim, shmem, 0>>>(...);
    return;
  }

  // --- fp8-Q path ---
  if (want_fp8q && ::vkernels::kernels::dsa_topk_logits_fits_lds_fp8q(num_heads, head_dim, block)) {
