```c
namespace {
// GB10 (sm_121) opt-in dynamic shared cap (verified on ds5): 101,376 B,
// and the opt-in WORKS (unlike gfx942's silent no-op past 64 KB). The
// fp32-Q kernel needs opt-in at H>=64 (66,048 B); the fp8-Q kernel at
// H>=128 (50,176 B); the wmma kernel at H>=128 (74,496 B).
constexpr int kGb10ShmemOptin = 101376;

bool fits_fp32q(int H, int D, int B) {
  const int bytes = (H*D + H + B*D + B) * 4;
  return bytes > 0 && bytes <= kGb10ShmemOptin;
}
bool fits_fp8q(int H, int D, int B) {
  const int bytes = (H + B*D + B) * 4 + H*D;
  return bytes > 0 && bytes <= kGb10ShmemOptin;
}
// wmma: shared = (D*H + B*kBK)*2 + (H + B)*4, with kBK=64.
// ALSO register-safe: kTh = (B/16)*(H/16)*32 <= 512 (acc[kFragsN] fragments
// at ~8 regs each + a/b frags; 1024 threads at H=128,B=64 exceeds the
// 65536 regs/block). H%16, D%64, B%16 required by the 16x16x16 fragment.
constexpr int kBK = 64;
bool fits_wmma(int H, int D, int B) {
  if (H <= 0 || D <= 0 || B <= 0) return false;
  if (H % 16 != 0 || D % kBK != 0 || B % 16 != 0) return false;
  const int kTh = (B / 16) * (H / 16) * 32;
  if (kTh > 512) return false;   // register wall
  const int bytes = (D*H + B*kBK) * 2 + (H + B) * 4;
  return bytes <= kGb10ShmemOptin;
}
}
```

