// shape constraints -- H%16, D%64, B%16 -- plus an H<=128 register cap
// (kMaxNF=8) and the opt-in LDS cap that includes the sAcc[B][H] staging).
// Pure arithmetic on documented device caps.
static bool fits_lds_wmma(int H, int D, int B) {
  if (H <= 0 || D <= 0 || B <= 0) return false;
  if (H % 16 != 0 || D % kBK != 0 || B % 16 != 0) return false;
  if (H > kMaxNF * 16) return false;          // register cap (kMaxNF=8 -> H<=128)
