  constexpr int kTh = kFragsM * kFragsN * 32;
  const int shmem =
      (D * H + B * kBK) * 2 + (H + B) * (int)sizeof(float) + B * H * (int)sizeof(float);
  // Opt in to the larger-than-default shared region ONCE per kernel
