  // D%64==0, B%16==0, H<=128 (kMaxNF=8 register cap) and must fit the
  // opt-in LDS cap. The wmma kernel is a template on (H,D,B); only the
  // GLM-5.3 family (H in {16,32,48,64,80,96,112,128}, D=128, B=16/32/48/
  // 64) is instantiated below. Other fitting shapes fall through to the
  // scalar kernels.
  if (want_wmma && fits_lds_wmma(H, D, B)) {
    const int shmem = (D * H + B * kBK) * 2 + (H + B) * (int)sizeof(float) +
                      B * H * (int)sizeof(float);
    dim3 blockdim((B / 16) * (H / 16) * 32);
#define LAUNCH_WMMA(h, d, b)                                            \
  do {                                                                  \
    static const bool inited_ = [] {                                    \
      cudaFuncSetAttribute(                                             \
          (const void*)dsa_topk_logits_kernel_wmma<h, d, b>,            \
          cudaFuncAttributeMaxDynamicSharedMemorySize, shmem);          \
      return true;                                                      \
    }();                                                                \
    (void)inited_;                                                      \
    dsa_topk_logits_kernel_wmma<h, d, b><<<grid, blockdim, shmem, 0>>>( \
        q, kv, w, sl, pt, o, max_table_len, max_seq_len, split_kv);     \
  } while (0)
    // GLM-5.3 indexer family: H in {32,64,128} (and 16), D=128, B in
    // {16,32,48,64} (B%16). Instantiate the shapes the harness exercises.
    if (H == 32 && D == 128 && B == 64)      { LAUNCH_WMMA(32, 128, 64); return; }
    if (H == 64 && D == 128 && B == 64)      { LAUNCH_WMMA(64, 128, 64); return; }
    if (H == 128 && D == 128 && B == 64)     { LAUNCH_WMMA(128, 128, 64); return; }
